"""Activity-signature rules: normalized budget-row/tafsil titles -> municipal activity -> proposed CC -> native L2.

rule(rule_id, include_regex, cc, default_native_L2|None, compat_natives, kind, activity_label, exclude_regex)
kind: op=direct operating service, cap=capital project, sup=internal support function,
      per=personnel/shared resource, CCONLY=proposed CC without native equivalent,
      AMB=ambiguous, AMBREF=ambiguous unless authoritative native budget-row title agrees,
      INS=generic input (no activity evidence), NA=financing/investment, GENERIC=placeholder (try next field)
First match wins; order encodes collision guards (activity before location; construction vs maintenance).
"""
import re

def norm(t):
    t = '' if t is None else str(t)
    t = t.replace('ي', 'ی').replace('ك', 'ک').replace('ة', 'ه').replace('ۀ', 'ه').replace('أ', 'ا').replace('إ', 'ا').replace('ئ', 'ی')
    t = re.sub(r'[\u200c\u200f\u200e\u0640\xa0]', ' ', t)
    t = re.sub(r'[ـ\-–—_/\\,،()\[\]{}:;.«»"\']+', ' ', t)
    return re.sub(r'\s+', ' ', t).strip()

def w(x):
    """whole-word alternative group"""
    return r'(?:^| )(?:' + x + r')(?: |$)'

GREEN = 'فضای سبز'
R = []
def rule(rid, inc, cc, nat, compat=(), kind='op', act='', exc=None):
    R.append((rid, re.compile(inc), re.compile(exc) if exc else None, cc, nat, tuple(compat) or ((nat,) if nat else ()), kind, act))

