def classify(text):
    t = norm(text)
    if not t:
        return None
    for rid, inc, exc, cc, nat, compat, kind, act in R:
        if inc.search(t) and not (exc and exc.search(t)):
            return dict(rule=rid, cc=cc, native=nat, compat=compat, kind=kind, act=act, text=t)
    return None
